referenceSolutions.javascript:
function resetTalliesFirstQualifyingSlip(readings, k) {
  const a=readings; let out=[];
  let total=0;for(const x of a){total=x===0?0:total+x;out.push(total);}
  return out.find(x=>x>=k)??-1;
}

